import sys

def main():
    n = int(sys.stdin.readline())
    h = list(map(int, sys.stdin.readline().split()))

    while True:
        changed = False
        for j in range(n - 1):
            if h[j] + 2 <= h[j + 1]:
                h[j] += 1
                h[j + 1] -= 1
                changed = True
        if not changed:
            break
    print(' '.join(map(str, h)))

main()
